 function openReview(){const rows=historyFoods(data()).filter(r=>nutritionNeedsReview(r.food));state.history=rows;ctx.openSheet('Nutrition review',`<section class="food-studio">${back()}${intro('A CLOSER LOOK','Make the unknowns visible.','Missing nutrition and calorie/macro disagreements are retained until you review the original food or label. Blank values stay unknown.')} ${rows.length?rows.map(({date,food},i)=>`<button type="button" class="fs-history-row" data-fs="review-food" data-index="${i}"><span><small>${esc(ctx.dateLabel(date))}</small><b>${esc(food.name)}</b><small>${food.reviewRequired?'Calories and macros need review':'Some nutrition is unknown'}</small></span><span>${ctx.icon('arrow')}</span></button>`).join(''):notice('Your food entries have no missing nutrition or outstanding review flags.')}</section>`);}
